const __aivicBundle_8_validateIssueDataIntegrity = (() => {
  function validateIssueDataIntegrity(
    input: IssueDataValidationInput
  ): IssueDataValidationResult {
    const violations: string[] = [];
  
    // 必須フィールドの確認
    if (!input.issueId || input.issueId.trim() === "") {
      violations.push("必須フィールド欠落");
    }
    if (!input.issueContent || input.issueContent.trim() === "") {
      violations.push("必須フィールド欠落");
    }
    if (!input.issueType || input.issueType.trim() === "") {
      violations.push("必須フィールド欠落");
    }
  
    // 優先度スコアの範囲チェック（0～100）
    if (
      typeof input.priorityScore !== "number" ||
      input.priorityScore < 0 ||
      input.priorityScore > 100
    ) {
      violations.push("優先度スコアが範囲外");
    }
  
    // 影響度の妥当性チェック
    if (
      typeof input.impactDegree !== "number" ||
      input.impactDegree < 0 ||
      input.impactDegree > 100
    ) {
      violations.push("影響度が範囲外");
    }
  
    // 緊急度の妥当性チェック
    if (
      typeof input.urgencyLevel !== "number" ||
      input.urgencyLevel < 0 ||
      input.urgencyLevel > 100
    ) {
      violations.push("緊急度が範囲外");
    }
  
    // 抽出キーワードの確認
    if (
      !Array.isArray(input.extractedKeywords) ||
      input.extractedKeywords.length === 0
    ) {
      violations.push("必須フィールド欠落");
    }
  
    // 優先度と影響度の矛盾チェック
    if (
      typeof input.priorityScore === "number" &&
      typeof input.impactDegree === "number" &&
      input.priorityScore < 30 &&
      input.impactDegree > 80
    ) {
      violations.push("優先度と影響度の矛盾");
    }
  
    // 分析結果の妥当性チェック
    if (input.analysisResult) {
      if (
        !input.analysisResult.rootCauseCategory ||
        input.analysisResult.rootCauseCategory.trim() === ""
      ) {
        violations.push("分析結果の根本原因カテゴリが未設定");
      }
      if (
        typeof input.analysisResult.frequencyCount !== "number" ||
        input.analysisResult.frequencyCount < 0
      ) {
        violations.push("分析結果の発生頻度が不正");
      }
      if (
        typeof input.analysisResult.affectedTeamCount !== "number" ||
        input.analysisResult.affectedTeamCount < 0
      ) {
        violations.push("分析結果の影響チーム数が不正");
      }
    }
  
    const isValid = violations.length === 0;
  
    if (isValid) {
      // 優先度スコアから優先度ランクを決定
      let priorityRank = "低";
      if (input.priorityScore >= 70) {
        priorityRank = "高";
      } else if (input.priorityScore >= 40) {
        priorityRank = "中";
      }
  
      const normalizedContent = input.issueContent.trim();
  
      return {
        isValid: true,
        violationDetails: undefined,
        validatedIssueData: {
          issueId: input.issueId,
          normalizedContent: normalizedContent,
          validatedPriorityRank: priorityRank,
        },
      };
    }
  
    return {
      isValid: false,
      violationDetails: violations,
      validatedIssueData: undefined,
    };
  }
  return { validateIssueDataIntegrity };
})();
